// <<< ex-img map

export const IMG_SOURCES = Object.freeze({
  ek: Object.freeze({
    text: 'Exercise illustrations: Everkinetic (everkinetic.com), CC BY-SA 4.0',
    name: 'Everkinetic (everkinetic.com)', url: 'https://everkinetic.com/',
    licName: 'CC BY-SA 4.0', license: 'https://creativecommons.org/licenses/by-sa/4.0/',
  }),
  fdb: Object.freeze({
    text: 'Exercise photos: free-exercise-db (public domain)',
    name: 'free-exercise-db', url: 'https://github.com/yuhonas/free-exercise-db',
    licName: 'ملكية عامة', license: 'https://unlicense.org/',
  }),
});
/** Kept for older imports: the Everkinetic credit. */
export const IMG_CREDIT = IMG_SOURCES.ek;

const BASE = './ex-img/';

/** exId (library id, e.g. 'ex1') → { a: start URL, b: end URL, source: 'ek'|'fdb', credit } | null */
export function exerciseImages(exId) {
  const m = MAP[String(exId || '')];
  if (!m) return null;
  const [source, key] = m;
  return { a: `${BASE}${key}-a.webp`, b: `${BASE}${key}-b.webp`, source, credit: IMG_SOURCES[source].text };
}

/** Removes the element (or its figure wrapper) when an image fails, so nothing broken ever shows. */
const drop = (sel) => (ev) => { const t = ev.currentTarget; (sel ? t.closest(sel) : t)?.remove(); };

const img = (src, alt, cls, w, hgt, onerror) => h('img', { src, alt, class: cls, width: w, height: hgt, loading: 'lazy', decoding: 'async', draggable: 'false', onerror });

/** Small list thumbnail (end position). Returns null when the exercise has no image. */
export function exerciseThumb(exId) {
  const im = exerciseImages(exId);
  if (!im) return null;
  return h('span', { class: 'wk-exthumb', 'aria-hidden': 'true' }, img(im.b, '', '', 44, 44, drop('.wk-exthumb')));
}

/** Start/end figure pair with labels, a gentle alternating highlight (static under reduced motion) and the credit of its source. */
export function exerciseFigure(exId, name = '') {
  const im = exerciseImages(exId);
  if (!im) return null;
  const pane = (src, label, cls) => h('figure', { class: `wk-expane ${cls}` },
    img(src, `${name ? name + ' — ' : ''}${label}`, '', 360, 326, drop('.wk-exfig')), h('figcaption', {}, label));
  return h('section', { class: `wk-exfig is-${im.source}`, 'aria-label': 'شكل الحركة', 'data-src': im.source },
    h('div', { class: 'wk-expair' }, pane(im.a, 'البداية', 'is-a'), pane(im.b, 'النهاية', 'is-b')),
    creditLine('wk-excredit', im.source));
}

const link = (href, text, rel = 'noopener noreferrer') => h('a', { href, target: '_blank', rel, dir: 'ltr' }, text);
const credit = (s) => [link(s.url, s.name), ' · ', link(s.license, s.licName, 'noopener noreferrer license')];

/** Credit line with links. With a source: that source only ('ek' → "رسوم التمارين: Everkinetic · CC BY-SA 4.0",
 *  'fdb' → "صور التمارين: free-exercise-db · ملكية عامة"). Without one (library screen): both sources. */
export function creditLine(cls = 'wk-excredit', source = '') {
  const ek = IMG_SOURCES.ek, fdb = IMG_SOURCES.fdb;
  if (source === 'fdb') return h('p', { class: cls, lang: 'ar' }, 'صور التمارين: ', ...credit(fdb));
  if (source === 'ek') return h('p', { class: cls, lang: 'ar' }, 'رسوم التمارين: ', ...credit(ek));
  return h('p', { class: cls, lang: 'ar' }, 'رسوم التمارين: ', ...credit(ek), '، وصور: ', ...credit(fdb));
}
